import Darwin
@main
struct SelfTestMain {
    static func main() {
        let boundaryCompilationTests = BoundaryCompilationTests()
        boundaryCompilationTests.testOnlyPublicFrameworkBoundaryTypesAreLinked()
        let keepAwakeWorkspaceTests = KeepAwakeWorkspaceTests()
        keepAwakeWorkspaceTests.testKeepAwakeUsesFreshOwnedStateOneExplicitCommandAndReadback()
        keepAwakeWorkspaceTests.testKeepAwakeExitIsNotStateEvidenceAndLateResultIsRejected()
        keepAwakeWorkspaceTests.testKeepAwakeGateRejectsReentrantActionUntilTerminalReadback()
        keepAwakeWorkspaceTests.testKeepAwakeUnavailableRowHasNoActionAndOffMeansOnlyNotOwned()
        keepAwakeWorkspaceTests.testWorkspacePresentationIsExactNineOrStaticDisabledFallback()
        keepAwakeWorkspaceTests.testRelatedPublicFactsRemainReadOnlyAndTruthfullyScoped()
        let mirroringTests = MirroringTests()
        mirroringTests.testReadRequiresTwoMatchingOnlineSnapshotsAndHandlesHardwareMirror()
        mirroringTests.testAnonymousReadStateContainsNoDisplayHandles()
        mirroringTests.testPreviewUsesOneAppOnlyMutationAndExactReadback()
        mirroringTests.testPreviewRejectsOneManyRemoteSharingAndUnstableTopologiesWithoutWrite()
        mirroringTests.testAppOnlyFailureWithMatchingReadbackStillRollsBackAndReportsFailure()
        mirroringTests.testPreviewStalenessAfterMutationEndsLeaseAndRejectsLateResult()
        mirroringTests.testKeepCommitsOneSessionTransactionThenEndsPreviewLeaseAndReadsAgain()
        mirroringTests.testEscapeTimeoutWakeReloadOwnerEOFAndHelperFailureRevertExactly()
        mirroringTests.testOwnerCrashAutomaticallyRevertsAppOnlyState()
        mirroringTests.testRollbackTruthIsPartialWhenSessionChangedExternally()
        mirroringTests.testUndoRequiresFullUnchangedKeptSnapshotAndExactReadback()
        mirroringTests.testLifecycleInvalidatesUndoWithoutWritingAndActivePreviewReverts()
        mirroringTests.testStaleKeepCancelsAppOnlyWithZeroSessionWrites()
        mirroringTests.testEveryViewRotatingLifecyclePathCancelsPreviewExactly()
        mirroringTests.testDisplayGateIsHeldForFullPreviewLeaseAcrossCoordinators()
        mirroringTests.testLateKeepRollsSessionBackExactlyBeforeLeaseRelease()
        mirroringTests.testFreshBoundaryExpectedSnapshotRejectsRaceWithoutStaleRestore()
        mirroringTests.testWMGateStaysBlockedForPreviewAndReturnsAfterTerminalReadback()
        let rowsAndSettingsTests = RowsAndSettingsTests()
        rowsAndSettingsTests.testUnsupportedRowsAreStableAndNonActionable()
        rowsAndSettingsTests.testDisabledRowsCannotDispatchMouseOrKeyboard()
        rowsAndSettingsTests.testActionRowsDispatchLeftClickAndKeyboardOnly()
        rowsAndSettingsTests.testSettingsKeySetIsExact()
        rowsAndSettingsTests.testAllSettingsKeysUseOneExactResourceAndFixedCopy()
        rowsAndSettingsTests.testSettingsResourceRejectsEveryIdentityAndPathMismatch()
        rowsAndSettingsTests.testSettingsFallbackRunsOnceOnlyForUnambiguousFailure()
        rowsAndSettingsTests.testAmbiguousAndLateSettingsResultsNeverFallbackOrRelabel()
        rowsAndSettingsTests.testSettingsBusyAndResolutionFailureAreFailClosed()
        let sleepShortcutLifecycleTests = SleepShortcutLifecycleTests()
        sleepShortcutLifecycleTests.testSleepRowsAreReadOnlyAXDisabledAndHaveExactManualCopy()
        sleepShortcutLifecycleTests.testDisplayPowerRequiresTwoExactOnlineNonemptySnapshots()
        sleepShortcutLifecycleTests.testReadFailuresAndTransitionsRemainClosed()
        sleepShortcutLifecycleTests.testEveryDisabledInteractionAndLifecycleLeavesForbiddenCountersAtZero()
        sleepShortcutLifecycleTests.testAllShortcutSlotsAreNilAndRejectedIncludingPermanentSleepReservations()
        sleepShortcutLifecycleTests.testLifecycleRotatesViewsAndDoesNotReleaseAnInFlightWMGate()
        let windowManagerTests = WindowManagerTests()
        windowManagerTests.testInventoryKeepsNativeContentAndIdentityOutOfAnonymousState()
        windowManagerTests.testStrictSnapshotValidationRejectsMalformedDenseResults()
        windowManagerTests.testFocusUsesFreshPrivateTargetOneCommandAndExactReadback()
        windowManagerTests.testActionExitNeverBecomesStateEvidence()
        windowManagerTests.testStaleSlotNoAXAndMissingCapabilityMakeNoCommand()
        windowManagerTests.testCloseMinimizeAndRestoreRequireFreshCapabilityAndReadback()
        windowManagerTests.testSendFollowSuccessHasMoveAndFocusWithSeparateReadbacks()
        windowManagerTests.testSendFollowHalfFailureRollsBackOnlyAfterExactFreshPreflight()
        windowManagerTests.testSendFollowReportsPartialTruthWhenRollbackIdentityOrTopologyIsLost()
        windowManagerTests.testFocusSpaceUsesExactTopologyOneCommandAndReadback()
        windowManagerTests.testBooleanActionsComputeDesiredStateAndNeverRetryToggle()
        windowManagerTests.testActionOnlyOperationsNeverClaimConfirmedState()
        windowManagerTests.testWarpRequiresAdjacentManagedAXTargetAndRelationReadback()
        windowManagerTests.testVendorReadbackCrashReleasesGateWithoutRetry()
        windowManagerTests.testSingleWindowReadbackRejectsUnrelatedMutationAsPartial()
        windowManagerTests.testRollbackRefusesWriteAfterAnyUnrelatedPostMoveChange()
        windowManagerTests.testNativePanelGenerationChangeRejectsSlotBeforeCommand()
        windowManagerTests.testGateRejectsReentrantMutationAndLateResult()
        if SelfTestRecorder.failures != 0 { exit(EXIT_FAILURE) }
        print("PASS self-tests \(SelfTestRecorder.assertions) assertions")
    }
}
